% Чтение данных
data = readtable('employment_data.xlsx', 'Sheet', 'данные');

% Извлечение возраста и статуса занятости
cancel_col = strtrim(string(data.c_acc028));
is_employed = ~(cancel_col == "\N");
employment_status = repmat("Unemployed", height(data), 1);
employment_status(is_employed) = "Employed";
age = data.age;

% Удаление пропусков
valid_rows = ~ismissing(age);
age_clean = age(valid_rows);
status_clean = employment_status(valid_rows);

% Визуализация: boxplot возраста по статусу занятости
figure;
boxplot(age_clean, status_clean);
xlabel('Employment Status');
ylabel('Age');
title('Age Distribution by Employment Status');

% Признаки и коэффициенты логистической регрессии
features = {'Major', 'Age', 'MaritalStatus', 'Ethnicity', 'CulturalLevel', 'Gender'};
coeffs = [0.002041, -0.039272, -0.045125, -0.114960, -0.146593, -0.349620];

% Сортировка по абсолютному значению
[~, sortIdx] = sort(abs(coeffs), 'descend');
sortedFeatures = features(sortIdx);
sortedCoeffs = coeffs(sortIdx);

% Визуализация
figure('Position', [100 100 800 400]);
hold on;
posIdx = sortedCoeffs > 0;
negIdx = sortedCoeffs <= 0;
barh(categorical(sortedFeatures(posIdx)), sortedCoeffs(posIdx),...
    'FaceColor', [0.2 0.6 0.8], 'BarWidth', 0.6);
barh(categorical(sortedFeatures(negIdx)), sortedCoeffs(negIdx),...
    'FaceColor', [0.8 0.3 0.2], 'BarWidth', 0.6);
grid on;
xlabel('Коэффициент регрессии', 'FontSize', 12, 'FontWeight', 'bold');
title('Важность признаков: логистическая регрессия', 'FontSize', 14, 'FontWeight', 'bold');
xline(0, '--k', 'LineWidth', 1.2);
legend({'Положительное влияние', 'Отрицательное влияние'}, 'Location', 'southeast');

% Важность признаков случайного леса (Gini importance)
features = {'Age', 'Major', 'CulturalLevel', 'Gender', 'MaritalStatus', 'Ethnicity'};
importance = [0.543081, 0.171977, 0.095917, 0.067382, 0.063566, 0.058077];

% Сортировка
[vals, idx] = sort(importance, 'descend');
sortedFeatures = features(idx);
sortedImportance = vals;

% Визуализация
figure('Position', [200 200 750 400]);
barh(categorical(sortedFeatures), sortedImportance,...
    'FaceColor', [0.44 0.23 0.7], 'BarWidth', 0.7);
xlim([0 ceil(max(sortedImportance)*10)/10 + 0.05]);
grid on;
xlabel('Важность признака (Gini)', 'FontSize', 13, 'FontWeight', 'bold');
title('Важность признаков: случайный лес', 'FontSize', 15, 'FontWeight', 'bold');

% Добавление числовых меток
textOffset = 0.015;
for i = 1:length(sortedImportance)
    text(sortedImportance(i) + textOffset, i,...
        sprintf('%.4f', sortedImportance(i)),...
        'FontSize', 11, 'VerticalAlignment', 'middle');
end
